"""Official rollout with fixed input selection; generated by the cold builder."""
from __future__ import annotations
def eval_remote_policy(task_name: str, task_env, args: dict[str, Any], model_client, st_seed: int, *, usr_args: dict[str, Any], test_num: int=100, video_size: str | None=None, instruction_type: str | None=None) -> tuple[int, int]:
    print(f"\x1b[34mTask Name: {args['task_name']}\x1b[0m")
    print(f"\x1b[34mPolicy Name: {args['policy_name']}\x1b[0m")
    expert_check = False
    frequency = int(usr_args.get('frequency', usr_args.get('ctrl_freq', 30)))
    action_type = str(usr_args.get('action_type', 'joint'))
    task_env.suc = 0
    task_env.test_num = 0
    now_id = 0
    succ_seed = 0
    now_seed = st_seed
    clear_cache_freq = args['clear_cache_freq']
    args['eval_mode'] = True
    consecutive_env_errors = 0
    for fixed_case in fixed_cases:
        now_seed = fixed_case['seed']
        now_id = fixed_case['now_ep_num']
        fixed_record('fixed_input_started', fixed_case)
        render_freq = args['render_freq']
        args['render_freq'] = 0
        episode_info = {'info': {}}
        args['render_freq'] = render_freq
        try:
            fixed_setup(task_env, now_ep_num=now_id, seed=now_seed, is_test=True, **args)
        except UnStableError:
            safe_close_env(task_env)
            print(f'skip unstable seed={now_seed} (eval setup)')
            raise RuntimeError('Fixed input setup was rejected; no replacement seed or retry')
        except Exception as e:
            safe_close_env(task_env)
            print(f'skip seed={now_seed} setup error: {type(e).__name__}: {e}')
            raise RuntimeError('Fixed input setup was rejected; no replacement seed or retry')
        succ_seed += 1
        initialize_rollout_metadata(task_name, task_env)
        instruction = fixed_case['prompt']
        task_env.set_instruction(instruction=instruction)
        if task_env.get_instruction() != fixed_case['prompt']:
            raise RuntimeError('Actual instruction differs from the fixed prompt')
        if task_env.eval_video_path is not None:
            ffmpeg = subprocess.Popen(['ffmpeg', '-y', '-loglevel', 'error', '-f', 'rawvideo', '-pixel_format', 'rgb24', '-video_size', video_size, '-framerate', '10', '-i', '-', '-pix_fmt', 'yuv420p', '-vcodec', 'libx264', '-crf', '23', f'{task_env.eval_video_path}/episode{task_env.test_num}.mp4'], stdin=subprocess.PIPE)
            task_env._set_eval_video_ffmpeg(ffmpeg)
        succ = False
        rollout_steps = 0
        rollout_failed = False
        prepare_policy_case(model_client, task_name, now_seed, instruction, action_type)
        reset_policy(model_client)
        try:
            while not is_episode_end(task_env):
                observation = task_env.get_obs()
                xpl_obs = robotwin_obs_to_xpolicylab(observation, instruction=task_env.get_instruction(), env_idx=0, frequency=frequency, task_env=task_env)
                model_client.call(func_name='update_obs', obs=xpl_obs)
                action_chunk = normalize_action_chunk(model_client.call(func_name='get_action'))
                if len(action_chunk) == 0:
                    raise RuntimeError('Policy returned an empty action chunk.')
                for action_idx, action in enumerate(action_chunk):
                    flat_action, robotwin_action_type = xpolicylab_action_to_robotwin(action, action_type=action_type, current_observation=observation)
                    task_env.take_action(flat_action, action_type=robotwin_action_type)
                    rollout_steps += 1
                    if task_env.eval_success:
                        succ = True
                        break
                    if is_episode_end(task_env) or action_idx + 1 == len(action_chunk):
                        break
                    observation = task_env.get_obs()
                    xpl_obs = robotwin_obs_to_xpolicylab(observation, instruction=task_env.get_instruction(), env_idx=0, frequency=frequency, task_env=task_env)
                    model_client.call(func_name='update_obs', obs=xpl_obs)
                if succ:
                    break
        except Exception:
            rollout_failed = True
            print('\n\x1b[91mPolicy rollout error:\x1b[0m')
            print(traceback.format_exc())
        if task_env.eval_video_path is not None:
            task_env._del_eval_video_ffmpeg()
        notify_trial_end(model_client, task_name, now_seed, succ)
        if rollout_failed:
            raise RuntimeError('Fixed-input rollout error; preserve the input and stop, no replay')
        consecutive_env_errors = 0
        if succ:
            task_env.suc += 1
            print('\x1b[92mSuccess!\x1b[0m')
        else:
            print('\x1b[91mFail!\x1b[0m')
        now_id += 1
        task_env.close_env(clear_cache=(succ_seed + 1) % clear_cache_freq == 0)
        if task_env.render_freq:
            task_env.viewer.close()
        task_env.test_num += 1
        fixed_record('fixed_input_completed', fixed_case, success=bool(succ), action_steps=rollout_steps)
        print(f"\x1b[93m{task_name}\x1b[0m | \x1b[94m{args['policy_name']}\x1b[0m | \x1b[92m{args['task_config']}\x1b[0m | \x1b[91m{args['ckpt_setting']}\x1b[0m\nSuccess rate: \x1b[96m{task_env.suc}/{task_env.test_num}\x1b[0m => \x1b[95m{round(task_env.suc / task_env.test_num * 100, 1)}%\x1b[0m, current seed: \x1b[90m{now_seed}\x1b[0m\n")
    return (now_seed, task_env.suc)
